window.K3_QRAW.push.apply(window.K3_QRAW, [{"id": "edu-psych|xl-03|b42|12", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 12, "q": "【2019年311真题34】马斯洛将人的五种基本需要划分为成长性需要和缺失性需要两大类。下列选项中属于成长性需要的是（）", "opts": ["自我实现需要", "安全需要", "归属需要", "尊重需要"], "a": 0, "exp": "成长性需要包括求知与理解的需要、美的需要、自我实现的需要。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b42|13", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 13, "q": "【2019年311真题38】在学习某一技能几次都失败后，最容易放弃这一学习任务的是（）", "opts": ["具有掌握学习目标取向的学生", "具有表现目标取向的学生", "具有趋于表现目标取向的学生", "具有逃避表现目标取向的学生"], "a": 3, "exp": "’“容易放弃”表明此学生具有的是表现目标取向，不是掌握目标取向。在表现目标取向中，任务失败后会对自我价值造成威胁、放弃学习任务以保护自我的学生，属于逃避表现目标取向。C选项具有趋于表现目标取向的学生关注如何考得好、超越他人来表现自己。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b42|14", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 14, "q": "【2020年311真题36】具有掌握学习目标取向的学生对智力往往持（）", "opts": ["增长观", "实体观", "多元观", "三元观"], "a": 0, "exp": "具有掌握学习目标取向的学生往往持有增长观。增长观指的是相信智力和能力都可以通过努力和持续地练习来发展和提高的观念。这种观念认为，我们的能力固然有限，但是我们不断学习和尝试新的事物可以让我们变得更聪明、更有能力。掌一·第三章学习动机握学习目标取向的学生认为自己可以通过不断地努力和学习来提高自己的能力，而不是将智力视为不可改变的实体。B选项实体观则相反，它认为智力是不可变的固定量，人们只能发挥天生具有的才智。C选项多元观认为智力是可以在不同的领域展现的，存在多种方式来表达智力。D选项三元观认为智力是由天赋、动机和努力三个因素共同决定的。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b42|15", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 15, "q": "【2022年311真题35】根据动机的自我决定理论，下列选项中，反映学生自主需要的是（", "opts": ["小张希望得到同学们的认可和尊重", "小王希望自己规划假期活动", "小赵希望自己的英语发音越来越好", "小李希望得到最新款手机"], "a": 1, "exp": "自主需要指个体能感知到做出的行为是出于自己的意愿的，是由自我决定的，即个体的行为是自愿且能够自我控制的。因此B选项小王希望自己规划假期活动最能反映学生自主需要。A选项跟马斯洛的需要层次理论有关。C选项是认知内驱力，D选项是外部的物质需求。自我决定理论：（1）代表人物：美国心理学家德西和瑞安。（2）基本假设：人是积极的有机体，具有与生俱来的心理成长和发展动力，使其努力掌握环境中的挑战，并将其整合到自我概念中。自我决定就是一种关于经验选择的潜能，是在充分认识个人需要和环境信息的基础上，个体对行动所做出的自由的选择。（3）三个基本需要：自我决定理论涉及人的三个基本需要，分别是胜任需要、归属需要和自主需要。（4）三种动机：自我决定理论把动机分为三类，即内部动机、外部动机和无动机。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b43|16", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 16, "q": "我们对优秀学生进行奖励，不仅可以激励优秀学生也可以激励一般学生，是因为一般学生受到了（）·第三章学习动机", "opts": ["直接奖励", "直接强化", "替代性强化", "替代性惩罚"], "a": 2, "exp": "本题考查的知识点是替代性强化。C选项，替代性强化是指观察到榜样的行为或行为结果而受到的强化。一般学生看到优秀学生获得了奖励自己也会努力学习，故C选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b43|17", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 17, "q": "与追求成功者相比较，害怕失败者倾向于选择（）", "opts": ["比较难的任务", "比较容易的任务", "难度适中的任务", "非常难或非常容易的任务"], "a": 3, "exp": "本题考查的知识点是成就动机理论。根据阿特金森的成就动机理论，成就动机由两种具有相反倾向的部分组成，一种称之为力求成功，即人们追求成功和由成功带来积极情感的倾向性；另一种称之为避免失败，即人们避免失败和由失败带来的消极情感的倾向性。避免失败型的人倾向于选择非常容易或者非常难的任务，回避有50%把握的工作。选择非常容易的任务可以避免失败；选择过难的任务，即使失败也能找到借口以减少失败感。这种选择能防止自尊心受到伤害和产生心理烦恼，选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b43|18", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 18, "q": "学生经历了长时间的学习失败，做了多种努力也不能改变这种失败的现状后，表现出不听课、不做作业、成绩极差、不遵守纪律的行为特征，这种称为（）", "opts": ["习得性无助", "自我归因感", "期望效应", "学习困难"], "a": 0, "exp": "本题考查的知识点是韦纳的归因理论。习得性无助是当个体感到无论做什么事情都不会对自已的重要生活事件产生影响时所体验到的一种抑郁状态。题干中的学生属于破罐子破摔的心态，这是习得性无助的典型表现，选项。因素稳定性不稳定稳定√能力努力√工作难度√运气√韦纳成败归因理论的三维度分析表维度能控制性因素来源内在外在能控制不能控制√√√√√√√", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b43|19", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 19, "q": "学生把自己考试成绩差的原因归为试题太难太偏，这种归因属于（", "opts": ["内部、不稳定、可控的", "外部、稳定、不可控的", "内部、稳定、可控的", "外部、不稳定、不可控的"], "a": 1, "exp": "本题考查的知识点是韦纳的归因理论。韦纳认为人们倾向于将活动成口：的原因归结为能力高低、努力程度、任务难易、运气（机遇）好坏、身心状态和外界环境六个因素。这些因素又可以分别纳人内部归因和外部归因（内、外源维度）稳定性归因和不稳定性归因（稳定性维度）可控制归因和不可控制归因（可控性维度）三个维度之中。试题太难太偏，属于外部、稳定、不可控的因素。本题可使用排除法，任务难度在韦纳看来是外部的，排除A、C选项。同时，韦纳将难度归因为稳定的，排除D选项。本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b43|20", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 20, "q": "小峰认为输掉学校秋季篮球比赛是因为他们班运气不好，这种归因属于（", "opts": ["内部、不可控和不稳定的归因", "外部、可控和稳定的归因", "外部、不可控和稳定的归因", "外部、不可控和不稳定的归因"], "a": 3, "exp": "本题考查的知识点是韦纳的归因理论。美国心理学家韦纳对行为结果的归因进行了深人探讨，提出了系统的归因理论。人们倾向于将活动成败的原因归结为能力高低、努力程度、任务难易、运气（机遇）好坏、身心状态和外界环境六个因素。这些因素又可以分别纳人内部归因和外部归因（内、外源维度）稳定性归因和不稳定性归因（稳定性维度）可控制归因和不可控制归因（可控性维度）三个维度之中。运气是外部、不可控、不稳定的归因。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b43|21", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 21, "q": "小羽很想知道为什么钉子、铁块会沉人海底，而用钉子与铁块等原材料做成的轮船却可以浮在海面上。为此，小羽在学习浮力这一章内容时十分专注。根据学习动机的分）类，小羽的动机属于（", "opts": ["认知内驱力", "自我提高内驱力", "附属内驱力", "普遍内驱力"], "a": 0, "exp": "本题考查的知识点是奥苏伯尔的成就动机分类。奥苏伯尔认为，学校情境中的成就动机至少应包括三方面的内驱力，即认知内驱力、自我提高内驱力和附属内驱力。A选项，认知内驱力即一种学生渴望了解和理解，要求掌握知识以及系统闸述问题并解决问题的倾向。题干中，小羽是因为对为什么钉子、铁块会沉人海底，而用钉子与铁块等原材料做成的轮船却可以浮在海面上这个问题好奇产生的学习动机，属于认知内驱力.因此，A选项正确.回买夫注公次亏[才大】B选项，自我提高内驱力是个体要求凭自己胜任工作的才能和工作成就而赢得相应地位的愿望。自我提高内驱力与认知内驱力不一样，它并非直接指向学习任务本身。自我提高内驱力把成就看作是赢得地位与自尊心的根源，显然是一种外部的动机。C选项，附属内驱力是学生为了保持家长和教师等的赞许或认可而努力学习的一种动力。它是一种外部的动机。D选项，普遍内驱力为干扰选项，故排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b43|22", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 22, "q": "在一次英语考试中，小果考得很不好。班主任陈老师找她谈话时，小果说：“陈老师，我前段时间看到星座书上说我的星座最近几周都会很倒霉，果然这次就考砸了。”另一努力，这次总算有回报了。”对此下列说法正确的是（）", "opts": ["小果的归因属于外部、稳定、不可控因素", "彤彤的归因属于内部、不稳定、可控因素", "小果的归因方式会避免她有过大的学习压力，值得提倡", "彤彤和小果的归因方式虽然不同，但对学习行为并不会有影响"], "a": 1, "exp": "A选项，外部、稳定、不可控因素是工作难度，而题干中小果将考试成绩不佳归因于运气，运气是外部、不稳定、不可控的归因，所以不符合题意。B选项，内部、不稳定、可控的因素是努力，题干中彤彤将考试取得进步归因于努力，符合题意。C选项，小果将考试成绩不佳归因于运气，会自我原谅，不利于发现自身问题，不值得提倡，C选项错误。D选项，小果将考试成绩不佳归因于运气，不利于其发现自身的问题，这会导致其考试成绩越来越差；彤彤将考试取得进步归因于努力，这一归因会促使她继续努力。所以不同归因对学习行为存在影响，故D选项说法错误。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b43|23", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 23, "q": "下列说法中属于内控特征的归因是（）", "opts": ["我没有充分准备，导致考试成绩不理想", "不熟悉考场环境，导致我这次考试发挥失常", "老师命题超纲，导致我做不出那些难题怪题", "老师突然安排考试，因此我对成绩好坏不能把控"], "a": 0, "exp": "A选项，没有充分准备导致考试成绩不理想，体现的是归因于努力，努力属于内部的、可控的、不稳定的因素，符合题意，故本题选A选项。B选项，不熟悉考场环境导致考试发挥失常，这是归因于外界环境，环境属于外部、不可控的、不稳定的因素。C选项，命题超纲导致做不出题，这是归因于任务难易程度，任务难度属于外部、不可控的、稳定的因素。D选项，突然考试导致无法把控成绩，也是外部的、不可控的因素。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b43|24", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 24, "q": "对有自卑心理的学生，当其通过努力取得好成绩时，教师应引导他作（", "opts": ["外部、可控、稳定的归因", "内部、可控、不稳定的归因", "内部、不可控、稳定的归因", "外部、不可控、不稳定的归因"], "a": 2, "exp": "本题考查归因理论。韦纳认为人们倾向于将活动成败的原因归结为能一·第三章学习动机力、努力程度、任务难度、运气、身心状态和外界环境六个因素。同时，韦纳认为这六个因素可归为三个维度，内在性、稳定性、可控性。当有自卑心理的学生取得好成绩时，教师应当引导其做能力归因（内在、不可控、稳定的归因）以增强其自信心，克服自卑心理。故C选项为正确选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-03|b43|25", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-03", "chName": "", "sec": "基础练习", "no": 25, "q": "小张竞选学生会主席失败后说：“竞选演讲那天我生病了，状态不好。”小张把竞选失败归因于（）", "opts": ["不稳定的不可控因素", "稳定的可控因素", "稳定的不可控因素", "不稳定的可控因素"], "a": 0, "exp": "A选项，不稳定的不可控因素包括运气、外在环境及身心状况，题干中小张生病属于身心状况因素，A选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b47|1", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 1, "q": "【2007年311真题40】说明“做什么”和“怎么做”反映活动的具体过程和操作步骤的知识属于（）", "opts": ["描述性知识", "陈述性知识", "程序性知识", "条件性知识"], "a": 2, "exp": "本题选C选项，“程序性知识”是关于“做什么”和“怎么做”的知识。A选项“描述性知识”和B选项“陈述性知识”是关于“是什么”“为什么”“怎么样”的知识，是对事实、定义、规则和原理等的描述，比如知识的类型。D选项“条件性知识”，梅耶在安德森的基础上，将陈述性知识称为语义知识，将程序性知识分为具体情境的程序性知识和有关学习、记忆、问题解决的一般方法的条件性知识。比如做笔记是一种程序性知识，什么内容写多一点，什么内容写少一点，则属于条件性知识。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b47|2", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 2, "q": "【2007年311真题41】学生一旦在新信息与原有认知经验之间建立了逻辑联系，就可以利用相关的背景知识对新信息做出进一步的推理和预期，从而“超越给定的信息”，生成更丰富的理解。这一知识建构的心理机制是（", "opts": ["同化", "顺应", "平衡", "重组"], "a": 0, "exp": "本题的解题关键在于利用相关的背景知识，“超越给定的信息”，即在不改变认知结构的基础上，对新信息做进一步的推理和预期。这属于把外界事物纳入已有的认知结构中，是同化的过程。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b47|3", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 3, "q": "【2009年311真题40】在多次遇到邻居家的狗之后，儿童形成了对“狗”的基本理解，包括狗的一般体型特征、生活习性、典型行为等。儿童关于狗的知识的表征方式是）", "opts": ["图式", "命题", "表象", "产生式"], "a": 0, "exp": "图式是认知系统的组织结构。关于狗是什么的基本定义属于命题。如果只是了解狗的一般体形特征，则属于表象。产生式是程序性知识的主要表征方式。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b49|4", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 4, "q": "学生在掌握金属的一般特性之后，再学习金属铜和铁的具体特征，这种学习称作", "opts": ["并列结合学习", "总括学习", "类属学习", "重复学习"], "a": 2, "exp": "本题考查的知识点是知识学习的含义及种类。奥苏伯尔根据新知识与原有认知结构的关系，提出了3种认知同化过程，即下位学习、上位学习和并列组合学习。下位学习（又称类属学习）指将概括程度或包容范围较低的新概念或命题，归属到认知结构中原有的概括程度或包容范围较高的适当概念或命题之下，从而获得新概念或新命题的意义。题干是先学习金属的一般特性，再学习金属铜和铁的具体特点，新学习的内容与学生认知结构中已有观念产生了一种下位关系，这属于类属学习，选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b49|5", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 5, "q": "学生将新学的概念“橡皮擦”归到“文具”这一总的概念中，这种学习属于（", "opts": ["下位学习", "同位学习", "上位学习", "并列学习"], "a": 0, "exp": "本题考查的知识点是知识学习的含义及种类。根据新知识与原有认知结构的关系，可以分为下位学习、上位学习和并列组合学习。其中，下位学习又称类属学·第四章知识的建构知识及知识建构习，指将概括程度或包容范围较低的新概念或命题，归属到认知结构中原有的概括程度或包容范围较高的适当概念或命题之下，从而获得新概念或新命题的意义。题干中新学习的概念“橡皮擦”是原有“文具”这一总概念的一个特例，这种学习是下位学习。因此，本题正确答案为A。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b49|6", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 6, "q": "按照信息加工心理学的观点，学生能够回答“第二次世界大战的原因是什么”“人的心脏结构和血液循环有什么关系”等问题需要的是（）", "opts": ["陈述性知识", "程序性知识", "策略性知识", "默会知识"], "a": 0, "exp": "本题考查的知识点是知识的类型。安德森根据知识的功能将知识划分为陈述性知识和程序性知识。其中陈述性知识也叫“描述性知识”，它是个人有意识地提取线索，能够直接加以回忆和陈述的知识。主要用来说明事物的性质、特征和状态，用于区别和辨别事物。这类知识主要解决是什么、为什么、怎么样的问题。这种知识具有静态的性质。题干中所说原因是什么，关系是什么等就属于陈述性知识。因此，本题正确答案为A。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b49|7", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 7, "q": "如果识记某材料10遍刚好能背诵，那么一般情况下，识记多少追效果最好？（）", "opts": ["12", "15", "18", "20"], "a": 1, "exp": "本题考查的知识点是过度学习。过度学习又称为“过度识记”，是指达到一次完全正确再现后继续识记的记忆。实验证明，过度学习达到50%，即学习熟练程度达到150%时，学习的效果最好。题干中，如果识记某材料10遍刚好能背诵，那么一般情况下，学习熟练程度达到150%效果最好，即识记15追。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b49|8", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 8, "q": "以下关于引发和促进陈述性知识学习的描述，不正确的是（）", "opts": ["提问可引发学习的多种认知过程", "学习是要记住教学和课本中呈现的内容", "原有的知识能促进学生对新知识的学习", "学习的认知过程主要由教师来引发和促进"], "a": 1, "exp": "本题考查的知识点是陈述性知识的学习。陈述性知识的学习包括理解、巩固、运用三个彼此相互联系又相对独立的阶段。其中知识的理解是指学习者了解传递知识的语言文字符号的含义，并使其在头脑中唤起相应认知内容的过程。知识的理解一般是通过对教材的直观和概括化完成的，要求教师将重点放在如何帮助学生有效地理解、掌握这类知识上，注重学生对其符号或词语意义的获取，而不仅仅只是记住。故B选项说法错误。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b49|9", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 9, "q": "学生在掌握蔬菜的一般特性之后，再学习白菜、萝卜、黄瓜等蔬菜的具体特性，这类学习属于（）", "opts": ["上位学习", "组合学习", "并列学习", "下位学习"], "a": 3, "exp": "本题考查的知识点是下位学习。D选项，下位学习又称类属学习，是指将概括程度或包容范围较低的新概念或命题归属到认知结构中已有的、概括程度或包容范围更高的适当概念或命题之下，从而获得新概念或新命题的意义，简而言之，就是先学概括程度较高的知识，后学概括程度较低的知识。题干中，先学蔬菜的一般特性，再学萝卜、白菜等的具体特性，蔬菜的概括程度较高，萝下、白菜的概括程度较低，所以是下位学习，因此D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b49|10", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 10, "q": "关于陈述性知识和程序性知识的区别，以下表述错误的是（", "opts": ["就改变难度而言，陈述性知识改变较易，程序性知识改变较难", "就习得速度而言，陈述性知识习得较慢，程序性知识习得较快", "就知识的内涵而言，陈述性知识是静态的，程序性知识是动态的", "就意识控制程度而言，陈述性知识意识控制程度较高，程序性知识意识控制程度"], "a": 1, "exp": "本题考查陈述性知识和程序性知识的区别。A选项，在认知心理学家看来，由于学习陈述性知识基本单位所付出的代价相对低，即我们可以比较快地获得，因而对这些基本单位作出修正也是相对容易的。例如，对于像命题表象、线性排序，我们可以毫无困难地给予完善、组织和纠正。同陈述性知识相比，程序性知识仅在其早期的获得阶段容易改变，一旦它们在人的记忆中编好了程序，且达到自动化的程度后，再要对它们作出改变就相当困难，因为一旦人的加工系统对获得的程序放弃了监控之后，人在执行这一程序时不会再去考虑其中哪一步是否正确或哪一步是否会产生预期的行为。A选项表述正确。忘也较快；程序性知识学习速度较慢，需要大量的练习才会达到熟能生巧的程度。程序性知识一般属于过度学习，因而保持比陈述性知识牢固。B选项表述错误，可选。C选项，陈述性知识是一种静态的知识，它只是对事件的一种描述；程序性知识是一种动28S态的知识，例如如何驾驶一辆汽车就包含着许多的过程。C选项表述正确。D选项，从意识控制程度看，陈述性知识的意识控制程度较高，激活速度较慢，往往是有意识的搜寻过程；程序性知识的意识控制程度较低，激活速度较快。D选项表述正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b49|11", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 11, "q": "下列选项中，属于上位学习的是（", "opts": ["先学习三角形的概念，再学习三角形的性质", "先学习长方形的概念，再学习正方形的概念", "", "先学习“质量与能量”的关系，再学习“需求与价格”的关系"], "a": 2, "exp": "上位学习是指新概念、新命题具有较广的包容面或较高的概括水平，这时，新知识通过把一系列已有观念包含于其下而获得意义，新学习的内容便与学生认知结构中已有观念产生了一种上位关系。C选项先学习“蚂蚁”“松鼠”“鲸鱼”等，再学习“动物”的概念，属于上位学习。A选项属于并列组合学习，B选项属于下位学习，D选项属于并列组合学习。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b52|12", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 12, "q": "【2008年311真题45】学生因“凹透镜”知识掌握不好而影响了“凸透镜”知识的学习。这种迁移现象是（）", "opts": ["纵向迁移", "横向迁移", "一般迁移", "普遍迁移"], "a": 1, "exp": "横向迁移的知识之间是并列关系。纵向迁移的知识之间是上下位关系。“凹透镜”和“凸透镜”之间属于并列的知识关系。它们之间的迁移属于横向迁移。C选项和D选项是一样的，一般迁移又称为普遍迁移，指的是概念、基本原理而不是具体知识点之间的迁移。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b52|13", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 13, "q": "【2009年311真题41】形式训练说所涉及的迁移本质上是（）", "opts": ["水平迁移", "垂直迁移", "特殊迁移", "一般迁移"], "a": 3, "exp": "形式训练说指的是训练官能，认为各种官能可以像训练肌肉一样，通过练习增加能力。一般迁移是指将习得的一般原理、方法、原则和态度等进行迁移。可见,形式训练说所涉及的迁移本质上是一般迁移。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b52|14", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 14, "q": "【2013年311真题35】学习单词basket（篮子)有助于学习单词basketball（篮球）。这里所产生的迁移是（）", "opts": ["顺应性迁移", "低路迁移", "水平迁移", "特殊迁移"], "a": 3, "exp": "特殊迁移是具体的知识点之间的迁移，非特殊迁移也称为一般迁移，是原理之间的迁移。题目属于两个单词，即具体的知识点之间的迁移，为特殊迁移。A选项顺应性迁移和同化性迁移相对，顺应是改变原有认知结构来适应新知识的过程。B选项低路迁移是自动化技能之间的迁移，常用在动作技能学习领域。C选项水平迁移是属于同一层级难度知识之间的迁移，如学习直角、平角和钝角之间的迁移。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b52|15", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 15, "q": "【2015年311真题34】下列不属于迁移的是（）", "opts": ["吃一堑，长一智", "近墨者黑", "因喷废食", "温故知新"], "a": 1, "exp": "“近墨者黑”只是环境对人的影响。而迁移指一种学习对另一种学习的影知识的整合与应用响。A选项“吃一堑，长一智”指从错误中吸取教训，学习经验。这种经验可以迁移到：口：H来的问题和挑战中，使人们更有智慧、更加成熟，属于正向迁移。C选项“因废食”指由于一次不好的经验而失去了信心和动力，不再继续学习或尝试，属于负向迁移。D选项“温故而知新”有两种解释：①复习已学过的知识，会有新的体会和理解；②通过回忆过去，吸取历史经验，给认识现在提供参考。这都属于学习迁移。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b52|16", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 16, "q": "【2019年311真题36】在掌握了“心理过程”概念后，再学习“认知过程”这一概念，前一学习对后一学习的影响属于（）", "opts": ["水平迁移", "垂直迁移", "一般迁移", "逆向迁移"], "a": 1, "exp": "“心理过程”是上位概念，包括认知过程。上位概念对下位概念的影响是垂直迁移。此处为具体知识点之间的迁移，不属于C选项一般迁移，而是具体迁移。前一学习对后一学习的影响也不属于D选项逆向迁移，而是正向迁移。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b52|17", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 17, "q": "【2020年311真题37】某学生数学基础好，学习教育统计课程时，感觉学习很顺利。这种学习现象属于（）", "opts": ["横向迁移", "纵向迁移", "逆向迁移", "重组迁移"], "a": 1, "exp": "这种学习现象属于B选项纵向迁移。纵向迁移指的是在一个领域内，学习某种基础的知识或技能，然后将其迁移应用到更为高级或复杂的知识或技能上的过程。这个学生之前数学基础好，学习统计课程时，能够运用之前学习的数学知识帮助其学习统计课程，这是典型的纵向迁移的表现。基础的知识或技能上。C选项逆向迁移是指在一个领域内，学习某种高级的知识或技能，然后将其迁移应用到更为基础的知识或技能上。D选项重组迁移是指将一个领域内的不同元素进行重组，以解决与学习任务相关的问题。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b52|18", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 18, "q": "练习中，设计了用小数表示“千克”“克”之间关系的题目。这种做法体现的概念教学策略是（）", "opts": ["提供反例", "增强同伴互动", "提供变式", "增强学习动机"], "a": 2, "exp": "C选项，变式是指在概念教学中，通过提供不同情境下的具体实例，帮助学生把握概念核心。教师用“元、角、分”“米、分米、厘米”“千克、克”等不同计量单位引人和练习小数，本质都是“用十进制关系理解小数，仅改变了具体测量领域这一非本质属性,符合提供变式的策略,正确言9了7888A选项，反例用于排除概念的非本质属性（如用“0.5米不是整数”说明小数特征），题干中均为符合小数概念的正例，无反例，错误。B选项，同伴互动强调学生间的交流合作（如小组讨论），题干仅描述教师的教学设计，未涉及同伴互动，错误。D选项，增强学习动机通常通过兴趣激发（如故事、游戏）实现，题干核心是通过不同实例帮助学生理解概念，而非激发动机，错误。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b52|19", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 19, "q": "【2023年311真题38】学生把数学课上学到的记笔记方法运用到记英语课的笔记。从迁移发生的方式和范围看，这属于（）", "opts": ["零迁移", "特殊迁移", "非特殊迁移", "纵向迁移"], "a": 2, "exp": "A选项，零迁移亦称中性迁移，是迁移的一种类别，指一种学习对另一种学习不起作用或两种经验间无相互影响，迁移效果或迁移量为零。B选项，特殊迁移强调的是某一领域或课题的学习直接对学习另一领域或课题所产生的影响。D选项，纵向迁移是不同难度的两种学习之间的相互影响。将记数学笔记的方法迁移到英语笔记中属于学习方法的迁移，为非特殊迁移，也称为原理迁移、一般迁移，故选C选项。迁移类型：含义划分维度具体类型处于同一抽象和概括水平根据迁移的不同横向（水平)迁移的经验之间的相互影响。抽象和概括水平的经验之间的相处于不同抽象和概括水平纵向（垂直）迁移互影响经验之间的相互影咱。，第四章知识的建构例子直角、钝角、锐角、平角等概念之间的迁移。学了角的概念后，学习直角的概念。划分维度具体类型-般（普迪）迁移和动机等的迁移根据迁移内容的不同特殊迁移同化迁移物中去根据原有的认知结构是否发生变化顺应迁移变化重组迁移的情境正迁移积极影响。根据迁移的效果负迁移消极影响顺向迁移根据学习的先后顺序逆向迁移近迁移情境中。根据迁移范围的不同远迁移境中。续表例子含义一般原理、方法、策略、态度研究生备考时吃苦耐劳的品质影响到考公备考考研教育学的知识对考教师资具体的、特殊的经验的迁移格证内容的迁移举一反三原有认知结构中的概念“鱼”、不改变原有的认知结构，直由带鱼、草鱼、黄鱼等概念组接将原有的认知经验应用成。现在要学习鱼，把它纳到本质特征相同的一类事人“鱼”的原有结构，既扩充了鱼的概念，又获得了毁鱼这一新概念的意义日常生活中形成了报纸、书刊、广插、电视等概念，当这些概念将原有的经验应用于新情不能解释“新媒体”这个概念境时所发生的一种适应性时，就要在原有的经验系统中建立一个概括性更高的科学概念“媒体”来标志这一事物重新组合原有经验系统中的某些构成要素或成分，调对一些原有舞蹈或体操的动作进行调整或重新组合后，编排整各成分之间的关系或建出新的舞蹈或体操动作立新的联系，从而应用于新一种学习对另一种学习的学了英语，语文成绩提高了一种学习对另一种学习的学了英语，语文成绩下降了先学了教育史，影响了后学的先前的学习对后学的影响教育学原理后学的", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|20", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 20, "q": "小学语文识字教材《日月明》一课中，有这样几句表述：“日月明，鱼羊鲜，小土尘，小大尖”这种教学策略运用的迁移方式是（）", "opts": ["强调概括总结", "注重共同要素", "强调形式训练", "注重结构转化"], "a": 1, "exp": "此类识字教材是通过把含有共同要素的汉字组合在一起来帮助学生学习，注重找到汉字之间在部首、偏旁等方面的共同点，从而实现对新的汉字的迁移和识记。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|21", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 21, "q": "关于专家和新手，说法不正确的是（）", "opts": ["专家解决问题时，通常把新问题划归为某一特定的问题类型", "专家解决问题时，更容易在头脑中形成问题的直观表征", "专家解决问题时，倾向于利用问题图式解决问题", "专家解决问题时，注意更多的中间过程"], "a": 3, "exp": "专家不太注意中间过程，更看重对问题整体的把握。相比新手，专家依赖于经验形成的问题模式，不太注意步步为营的中间过程", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|22", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 22, "q": "在训练学生射击水下靶子之前，先给学生讲水的折射原理有利于提高训练成绩。可以用来解释这种现象的迁移理论是（）", "opts": ["关系理论", "共同要素说", "形式训练说", "概括化理论"], "a": 3, "exp": "本题考查的是迁移理论。贾德根据水下击靶实验提出了迁移的概括化理论（经验类化说），概括化理论主张对已有经验进行了概括，就可以完成从一个情境到另一个情境的迁移。其中水下击靶实验就说明了掌提原理有利于产生迁移，故D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|23", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 23, "q": "教师在教学中教会学生“going”的“ing”，再教学生学习playing，coming就能达到事半功倍的效果，可以解释这种学习现象的是（）", "opts": ["共同要素说", "形式训练说", "概括化理论", "实质训练说"], "a": 0, "exp": "·共同要素说由美国心理学家桑代克和武德沃思提出，他们认为学习迁移的产生是由于两种学习情境存在共同要素或共同成分。共同要素说对学习迁移具有重大的影响。应用在教学上，一般会收到良好的效果。例如：小学生学习了“going”的\"ing..\"就会拼“moming、playing、coming..”而且记忆方便。故选A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|24", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 24, "q": "孔子说：“举一隅，不以三隅反，则不复也”这句话说明的学习现象是（）", "opts": ["学习定势", "学习迁移", "学习兴趣", "学习习惯"], "a": 1, "exp": "本题考查学习迁移的定义。学习迁移也称训练迁移，是指一种学习对另旁通”等即反映了学习的迁移。题干中“举一隅，不以三隅反，则不复也”的意思是从一件事情类推而知道其他许多事情。比喻善于学习，能够由此及彼。符合学习迁移的定义。因此B选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|25", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 25, "q": "训练学生估计不同大小的长方形的面积，一段时间后，测试结果发现学生估计长方形面积的能力提高，而估计圆形面积的能力并未提高。这个实验可以支持（）", "opts": ["形式训练说", "共同要素说", "概括化理论", "关系转换理论"], "a": 1, "exp": "本题考查早期迁移理论。桑代克在1901年的“形状知觉”实验中证实了共同要素说。在实验研究的基础上，他提出只有当两种情境中有相同要素时才能产生迁移。其后伍德沃斯把共同要素说修改为共同成分说，即两情境中有共同成分时可以产生迁移。题干中，学生训练了估计不同大小长方形的面积但是没有训练估计圆形面积，即一、第四章知识的建构两种情境中没有相同要素，测试结果发现学生估计长方形面积的能力提高，而估计圆形面积的能力并未提高。所以，这个实验可以支持共同要素说。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|26", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 26, "q": "某老师认为学生对三角形定义的学习和总结，有助于正方形定义的学习。那么这位老师更多受到以下哪种理论的影响（）", "opts": ["共同要素说", "形式训练说", "元认知理论", "情境性理论"], "a": 0, "exp": "本题考查的是学习迁移的理论。A选项，共同要素说认为只有在原先的学习情境与新的学习情境有共同要素时，原先的学习才有可能迁移到新的学习中去。三角形与正方形都属于由直线构成的封闭图形，具有共同的要素。故A选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|27", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 27, "q": "小兰利用寒假自学了几种高效学习方法，这使得她加深了对之前学过的知识的理解，从迁移的角度看，这属于（）", "opts": ["顺向正迁移", "顺向负迁移", "逆向正迁移", "逆向负迁移"], "a": 2, "exp": "本题考查迁移的分类。顺向迁移是指先前学习对后继学习的影响；逆向进作用；负迁移是指两种学习之间相互干扰、阻碍，即一种学习对另一种学习产生消极的影响。本题中，小兰后学习的学习方法帮助她加深了对之前学过的知识的理解，属于逆向正迁移。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|28", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 28, "q": "某老师认为，通过做大量的应用题可以提高学生的思维能力、从而提高学生在考试中应用题的作答正确率。该老师的观点主要受以下哪一迁移理论影响（）", "opts": ["关系转化理论", "共同要素说", "概括化理论", "形式训练说"], "a": 3, "exp": "本题考查的是迁移的理论学说。D选项，形式训练说是最早的迁移理论，代表人物是沃尔夫。该观点认为迁移是通过对组成心的各种官能的训练，以提高各种能力如注意力、记忆力、推理力、想象力等而实现的。而且，迁移的产生是自动的。题干中强调通过做大量的应用题即通过大量的练习就能提高学生思维，从而提高正确率，体现了形式训练说的观点。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|29", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 29, "q": "根据学习迁移理论中的垂直迁移的定义，下列选项中，能体现垂直迁移的实例是", "opts": ["对“石”字的学习可能影响“磊”字的学习", "汉语拼音的学习会影响英语音标的学习", "校内形成的热爱劳动的良好习惯会影响校外的劳动表现", ""], "a": 3, "exp": "本题考查的是垂直迁移。垂直迁移,也叫纵向迁移,指处于不同抽象、概括水平的经验之间的相互影响。垂直迁移表现在两个方面：一是自下而上的迁移，即", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|30", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 30, "q": "周昕学习了1块等于10角、1厘米等于10毫米之后，推算1分钟等于10秒。这属于（）", "opts": ["顺向正迁移", "逆向正迁移", "顺向负迁移", "逆向负迁移"], "a": 2, "exp": "该题考查的是学习迁移的分类。根据迁移性质的不同，学习迁移可分为正迁移与负迁移，正迁移是指一种学习对另一种学习产生积极的促进作用；负迁移是指两种学习之间相互干扰、阻碍。根据迁移方向的不同，学习迁移可分为顺向迁移与逆向迁移，顺向迁移是指先前的学习对后来学习的影响；逆向迁移是指后继学习对先前学习的影响。题干描述的是先学习的“1块等于10角、1厘米等于10毫米”对后学习的1分钟等于多少秒的影响，属于顺向迁移；“推算1分钟等于10秒”是一种错误的迁移，属于负迁移，所以应该是顺向的负迁移，故本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-04|b54|31", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-04", "chName": "", "sec": "基础练习", "no": 31, "q": "小刘在日常生活中既能驾驶自己的汽车，也能驾驶其他不同型号的小轿车。小刘对不同类型汽车驾驶技术的迁移属于（）", "opts": ["高路迁移", "中路迁移", "低路迁移", "下路迁移"], "a": 2, "exp": "本题考查的是迁移的分类。学习迁移也称训练迁移，是指一种学习对另一种学习的影响，或习得的经验对完成其他活动的影响。根据迁移发生的自动化程度，可以将迁移分为低路迁移和高路迁移。首先排除B、D选项。A选项的高路迁移是指有意识地将某种情景中学到的抽象知识应用于另一种情境中的迁移，如学生在一种学习情境中抽取了一种规则、原理、范例、图式、然后运用于新的情境。C选项的低路迁移是指以一种自发的或自动的方式所形成的技能的迁移。这种迁移是通C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b57|1", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 1, "q": "【2007年311真题42】阅读、写作、运算等技能主要是（", "opts": ["运动技能", "动作技能", "策略技能", "心智技能"], "a": 3, "exp": "本题属于对识记性知识的考查。阅读、写作、运算等技能属于心智技能。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b57|2", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 2, "q": "【2008年311真题36】下列选项中，属于运动技能的是（", "opts": ["摇头", "系鞋带", "心算", "作文"], "a": 1, "exp": "A选项“摇头”不属于技能，更多的是一种本能。C选项“心算”和D选项“作文”属于心智技能。B选项“系鞋带”属于运动技能。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b57|3", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 3, "q": "【2010年311真题38】运动技能的表征方式是（）", "opts": ["命题", "语义网络", "命题网络", "产生式系统"], "a": 3, "exp": "运动技能的表征方式是产生式系统。A、B、C选项都是心智技能的表征后实夫注公众亏L价天方式。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b57|4", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 4, "q": "【2011年311真题36】心智技能区别于运动技能的主要特点是（", "opts": ["流畅性、简缩性和适应性", "简缩性、展开性和流畅性", "简缩性、内潜性和展开性", "观念性、内潜性和简缩性"], "a": 3, "exp": "心智技能具有观念性、内潜性和简缩性；运动技能则具有物质性、外显性和拓展性。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b57|5", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 5, "q": "【2019年311真题35】根据加里培林对技能的分类，阅读属于（", "opts": ["操作技能", "运动技能", "心智技能", "学习技能"], "a": 2, "exp": "根据加里培林对技能的分类，阅读属于心智技能。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b59|6", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 6, "q": "下列选项中，属于心智技能的是（", "opts": ["看到风景", "分析问题", "打字", "洗衣服"], "a": 1, "exp": "本题考查的知识点是技能的种类。心智技能也叫智力技能、认知技能，它是一种借助于内部力量调节、控制心智活动的经验，是通过学习而形成的合乎法则的心智活动方式。如默读、心算、写作、观察和分析等技能。分析问题是在头脑中进行的智力活动，其属于心智技能，故本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b60|7", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 7, "q": "【2007年311真题43】在操作技能的学习过程中，主要依靠视觉控制，各个动作要素之间的协调性差，常常出现顾此失彼现象的阶段是（）", "opts": ["操作定向阶段", "操作模仿阶段", "操作整合阶段", "操作熟练阶段"], "a": 1, "exp": "冯忠良把操作技能的形式过程分为四个阶段，即操作的定向、操作的模仿、操作的整合和操作的熟练。题干表述的各个动作要素之间协调性差，是处于操作模仿阶段。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b60|8", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 8, "q": "【2016年311真题37】某学生在体操技能训练中表现为：整体动作趋于协调连贯，多余动作有所减少，视觉控制逐渐让位于动觉控制，但动作技能尚未达到自动化。该学生的体操技能处于（）", "opts": ["操作定向阶段", "操作模仿阶段", "操作熟练阶段", "操作整合阶段"], "a": 3, "exp": "操作技能的学习包括定向、模仿、整合和熟练四个阶段。“整体动作趋于协调连贯，多余动作有所减少，视觉控制逐渐让位于动觉控制”属于操作整合、熟练阶段。但“尚未达到自动化”表明技能还没有完全熟练，所以该学生的体操技能处于操作整合阶段。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b60|9", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 9, "q": "【2024年311真题36】学生一边与同学讨论数学题的解题思路，一边顺手写下解答要点。这说明其书写的动作技能已经达到（）", "opts": ["认知阶段", "联系阶段", "定向阶段", "自动化阶段"], "a": 3, "exp": "A选项认知阶段是认识到“需要什么动作”和“怎么做”的过程，如果书写技能处于认知阶段，那只是知道接下来写什么，还没有动笔，与题意不符。B选项联系阶段是对各个独立的步骤进行合并或者组块，以形成更大的单元，还未达到自动化的程度。如果书写技能处于联系阶段，那只能专注于如何书写得更快更好。C选项定向阶段只是知道技能要如何开展，如果书写技能处于定向阶段，和A选项类似，都只是大概知道自己要写什么，怎么写。D选项自动化阶段代表技能已经高度熟练，不需要额外花多少精力即可完成。题目中，学生能边说边写，代表其对书写这一技能不需要额外花多少精力，已经达到了高度自动化的阶段，故本题选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b62|10", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 10, "q": "就动作技能的学习而言，“见者易，学者难”这句话强调的是（的重要性", "opts": ["言语指导", "示范", "反馈", "练习"], "a": 3, "exp": "“见者易，学者难”这句话的意思是观看别人做某项动作技能看似很简单，但是自己实际去练习和学习却很难。这突出强调了动作技能学习中练习的重要性。动作技能的获得需要大量重复地练习，以达到熟练和自动化，仅仅通过言语指导、示范和反馈是不够的，关键在于自己反复地进行刻意练习。所以“见者易，学者难”这句话强调的是练习对动作技能学习的重要性。选择D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b62|11", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 11, "q": "晓川在学习蛙泳时，首先在泳池边观察教练如何游泳，紧接着开始在教练的指导下分别练习手部的划水和腿部的蹬腿动作。晓川的学习属于动作技能形成阶段中的(）", "opts": ["认知阶段", "自动化阶段", "运动阶段", "联结阶段"], "a": 0, "exp": "本题考查菲茨与波斯纳的三阶段模式。菲茨与波斯纳提出了操作技能三阶段论，即认知阶段一联结阶段（即练习形成阶段）一自动化阶段。哪些动作，各动作的顺序怎样，从何处可以得到反馈等。此时，学生要选出原来已经掌技能的形成与培养握的部分技能，并按规定的程序将它们组合起来。这一阶段的主要结果是获得程序性知识。B选项，自动化阶段是动作的协调和技能的完善阶段，是动作技能形成的最后阶段。在此阶段，各个局部动作联合成为一个完整的自动化的动作系统。此时，技能的执行变得日趋自动化，操作极其流畅、准确和稳定。C选项，运动阶段不属于动作技能形成的阶段，故排除。D选项，联结阶段是把局部动作综合成更大单位，从认知方面转向动作方面，最后形成一个连贯的初步动作系统的阶段。在这一阶段，操作技能主要发生两类变化：一是先前流为互相协调一致的、稳定的总技能。题干中晓川在观察完教练如何游泳后，分别练习手部与腿部动作符合认知阶段的特点。因此A选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-05|b62|12", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-05", "chName": "", "sec": "基础练习", "no": 12, "q": "小文同学在上课时可以一边快速记笔记一边听老师的讲授，小文记笔记的动作处于技能形成的（", "opts": ["联结阶段", "巩固阶段", "认知阶段", "自动化阶段"], "a": 3, "exp": "本题考查动作技能的形成理论。A选项，联结阶段，是对各个独立的步骤进行合并或者“组块”，以形成更大的单元。在这一阶段，学习者的注意力已从认知转向动作，逐渐从个别动作转向动作的协调与组织。开始把个别动作结合起来，以形成比较连贯的动作。B选项，巩固阶段为干扰选项。C选项，认知阶段主要是对示范动作，或者参考书、参考图示进行观察，需要了解所要学习的动作技能的动作结构和特点，以及各组成动作之间的联系，从而在头脑中形成动作映象。327931637888D选项，动作技能的学习进人自动化阶段，整个程序的完成不用经过刻意的注意。在自动化阶段中，学生所学习的动作技能的各个动作在时间和空间上已联合成为一个有机的整体并巩固下来，各个动作的相互协调已达到自动化。题干中，小文“可以一边快速记笔记一边听老师的讲授”，表明记笔记的技能已达到熟练和自动化。故本题选D选项。，第五章技能的形成", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|1", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 1, "q": "【2007年311真题44】学生用“一巴掌一巴掌打得资本主义鸣鸣地哭”来记忆马克思是“1818年5月5日”出生的这一历史事实，其所使用的学习策略属于（", "opts": ["注意策略", "复述策略", "编码组织策略", "精细加工策略"], "a": 3, "exp": "题干列举的是一种记忆术，根据学习策略的划分，属于精细加工策略。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|2", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 2, "q": "【2008年311真题37】在学习过程中，通过自我监控、自我调节等方式来促进学习的策略是(", "opts": ["元认知策略", "资源管理策略", "精细加工策略", "组织策略"], "a": 0, "exp": "本题属于识记性知识的考查。学习策略包括认知策略、元认知策略和资源管理策略。元认知策略包括计划策略、监察策略和调节策略。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|3", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 3, "q": "【2009年311真题43】“学会如何学习”的实质是（）", "opts": ["学会在适当条件下使用适当策略", "掌握科学概念与原理", "掌握大量言语信息", "形成学习兴趣"], "a": 0, "exp": "学会如何学习的实质是学会使用学习策略。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|4", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 4, "q": "【2009年311真题44】研究表明，专家棋手在扫视实战棋局5秒之后，能准确再现20多个棋位，而新手仅能记住4到5个棋位。对于这一事实的合理解释是（", "opts": ["专家的观察力敏锐", "专家的记忆力敏捷，第六章学习策略及其教学", "专家有较高的智力水平", "专家贮存了大量有关棋局的知觉模式"], "a": 3, "exp": "7本题容易错选B选项，其实并不是记忆力好的人就是专家，专家能再现多个位置，也不是单纯依靠记忆，更多的是依赖之前的经验，他们在头脑中贮存了大量有关棋局的知觉模式。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|5", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 5, "q": "【2010年311真题37】在学习“gas一煤气”这一单词时，学生加人了中介词，成了“gas一该死一煤气\"。该学生使用的策略是（）", "opts": ["精加工策略", "组织策略", "复述策略", "计划监控策略"], "a": 0, "exp": "题干中使用的记忆术属于精(细)加工策略。精(细)加工策略是一种将新学材料与头脑中已有知识联系起来,从而增加新信息的意义的深层加工策略。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|6", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 6, "q": "【2012年311真题35】在期末复习时，学生采用将课文内容以列结构提纲、画网络图的方法来帮助记忆。这种学习策略属于（）", "opts": ["复述策略", "精加工策略", "组织策略", "资源管理策略"], "a": 2, "exp": "课文内容以列提纲、画图表的方式帮助记忆，属于组织策略。①311真题中又将精细加工策略称为精加工策略，在不同年份的真题中表述可能不同，两种表述皆正确。学习策略概述学习策略", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|7", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 7, "q": "【2016年311真题36】某学生花20分钟学习一首短诗刚好成诵。为了防止遗忘，他又继续学习了10分钟。这种学习属于（）", "opts": ["适度学习", "过度学习", "掌握学习", "意义学习"], "a": 1, "exp": "过度学习是在完成了学习任务之后又在原有的任务上进行更多的练习。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|8", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 8, "q": "【2016年311真题38】学生采用画图表或列提纲的方式整理所学知识。这种学习策略属于（）", "opts": ["资源管理策略", "元认知策略", "精加工策略", "组织策略"], "a": 3, "exp": "组织策略是个体获取信息、解释或描述事物和把信息组织成有意义的类别，整合所学新知识之间、新旧知识之间的内在联系，形成新的知识结构的策略。常见的组织策略有画图表、列提纲等。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|9", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 9, "q": "【2017年311真题35】学生学习时用简洁的语词写出材料中的主要观点、次要观点以及各观点之间的关系。这种学习策略属于（）", "opts": ["精加工策略", "计划策略", "调节策略", "组织策略"], "a": 3, "exp": "通过简洁的词语进行概括，写出材料中的各种观点及各观点之间的关系的学习策略属于组织策略。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|10", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 10, "q": "【2018年311真题35】根据过度学习原则，如果一个学生经过4次复述刚好可记住某个英语单词，那么他学习该词最适宜的复述次数应该是（", "opts": ["5次", "6次", "7次", "8次"], "a": 1, "exp": "过度学习指学习程度为150%的学习，即经过4次复述可以记住后，再复述2次，共6次。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|11", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 11, "q": "【2018年311真题38】将电话号码8585885编成“帮我帮我帮帮我”以帮助记忆，这种方法可称之为（）", "opts": ["语义复述", "精加工", "组织策略", "情景性复述"], "a": 1, "exp": "谐音联想法属于精细加工策略。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|12", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 12, "q": "【2020年311真题35】为了顺利背诵课文，某学生在理解课文各个段落意义的基础上，认真整理了各段落之间的关系。这种学习策略是（）", "opts": ["监督策略", "复述策略", "精致策略", "组织策略"], "a": 3, "exp": "列提纲、做图表、运用理论模型等属于学习策略中的组织策略。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|13", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 13, "q": "【2022年311真题36】在学习英语单词时，某同学特别注重单词运用的语境。这种学习策略属于（）", "opts": ["复述策略", "组织策略", "精细加工策略各", "资源管理策略"], "a": 2, "exp": "“特别注重单词运用情景”属于精细加工策略中的注意联系实际生活。精细加工策略是一种将新学材料与头脑中已有知识联系起来，从而增加新信息的意义的深层加工策略。精细加工策略主要有：(1）记忆术。记忆术是一种有用的精加工技术，它能在新材料和视觉想象或语义知识之间建立联系。常见的记忆术有位置记忆法、首字联词法、谐音联想法、关键词法和视觉想象等。（2）做笔记。（3）提问策略。（4）生成性学习。（5）注意联系实际生活。（6）充分利用背景知识。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b67|14", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 14, "q": "【2024年311真题37】小张在复习备考时，注意调整自己的心理状态，避免不良情绪干扰学习。他所运用的这种学习策略属于（", "opts": ["精细加工策略", "努力管理策略", "组织策略", "注意策略"], "a": 1, "exp": "A选项精加工策略主要指的是一种将新学知识与头脑中已有知识联系起来，从而增加新信息的意义的深层加工策略。主要通过记忆术、做笔记、提问策略、进C选项组织策略主要通过列提纲、做图解、做表格的方式进行。D选项注意策略主要指的是学习者学会与掌握将注意指向或集中在所需要的信息上的方法、技巧或规则。通过明确告知学习目标、提示重难点、增强材料的吸引力、恰当使用独特刺激等方式开展。B选项努力管理策略指的是为了使学生维持自己的意志努力，需要不断地鼓励学生进行自我激励。小张在复习备考时，注意调整自己的心理状态，避免不良情绪干扰学习，就是在不断管理自己的努力，属于努力管理策略。二、分析论述题【参考答案】（1）精细加工策略是指将新学材料与头脑中已有知识联系起来，增加新信息的意义，从而帮助学习者将信息储存到长时记忆中去的学习策略。学习者运用记忆法、首字联词法、谐音联想法、关键词法和视觉想象法等方法，对要记忆的材料补充细节，举出例子、做出推论，或使之与其他观念形成联想，以达到长期保持的目的。（2）精细加工策略是一种将新学材料与头脑中已有知识联系起来，从而增加新信息的意义的深层加工策略。组织策略是个体获取信息、解释或描述事物和把信息组织成有意义的类别，整合所学新知识之间以及新旧知识之间的内在联系，形成新的知识结构的策略。·第六章学习策路及其教学前者是用旧知识处理新知识，使新知识符合原有的认知结构，方便更好地记忆。后者是将旧知识和新知识组织成新的认知结构。二者是不同的。（3）碎片化学习是通过对学习内容进行分割，利用碎时间进行的学习。①碎片化学习产生的原因有科技进步、阅读载体的变化和人们的浮躁求快心理等。当下流行的碎片化学习模式是应运而生的而不是凭空捏造的。人们企图通过碎片化学习，用更短的时间了解更多知识。②它的优点是灵活性、针对性、吸收率更高。它的缺点是学习内容分散，不利于系统、深度地学习。③从精细加工策路的角度来说，精细加工需要利用原有的知识对新的信息进行处理，而经碎片化学习学到的知识琐碎，不成结构，很难进行深度的加工。④从组织策略的角度，碎片化学习得到的知识需要进行组织化、系统化，缺少知识结构，很难", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|15", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 15, "q": "为了准备两个月后的高考，小轩从寝室搬了出来，在学校附近一个安静的小区里租了一个单间，认真备考。小轩的行为属于学习策略中的（）", "opts": ["组织策略", "计划策略", "调节策略", "资源管理策略"], "a": 3, "exp": "本题考查的知识点是学习策略的分类。D选项，资源管理策略就是帮助学生有效地管理和利用环境和资源，以提高学习效率和质量，包括时间管理、环境管理、努力管理、资源利用管理。其中环境管理策略，即要注意调节自然条件，如流通的空气、适宜的温度、明亮的光线以及和谐的色彩等。其次，要设计好学习的空间，如空间范围、室内布置、用具摆放等因素。小轩的做法属于资源管理策略中的环境管理策略，故D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|16", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 16, "q": "在记忆二十四节气时，有人将节气的首字连成诗句“春雨惊春清谷天，夏满芒夏暑相连，秋处露秋寒霜降，冬雪雪冬小大寒”进行记忆。这里使用的学习策略属于）", "opts": ["复述策略", "组织策略", "调节策略", "精加工策略"], "a": 3, "exp": "本题考查的知识点是学习策略的分类。精加工策略包括：记忆术（如位置记忆法、缩减与编歌诀、谐音联想法、关键词法、视觉联想法），做笔记，提问，生成性学习，利用背景知识，联系实际等。记忆术是一种有用的精加工策略，它能在新材料和视觉想象或语义知识之间建立联系。“二十四节气歌”体现了缩减与编歌诀法。故D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|17", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 17, "q": "杨毅在学习过程中，将自己的笔记本划分成两半，一半记录老师土课时所讲的内容，另一半记录自己不懂的地方或重要的地方。杨毅在这一过程中使用的学习策略属于）", "opts": ["精加工策略", "计划策略", "组织策略", "监视策略"], "a": 0, "exp": "精加工策略是一种将新学材料与头脑中已有知识联系起来从而增加新信息的意义的深层加工策略。常用的精细加工策略有记忆术、做笔记、提问等。题干中杨毅运用做笔记的学习策略属于精加工策略，故选A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|18", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 18, "q": "兵兵在阅读过程中，发现有一段特别难懂，他先是再次阅读该段落，并在阅读完全文之后又回过头来对这一段进行理解，兵兵采用的学习策略更符合（）", "opts": ["精加工策略", "计划策略", "组织策略", "监视策略"], "a": 3, "exp": "监视策略指在认知活动中，根据认知目标不断反省和监控自己的认知活标准评价各种认知行动、策略的效果。题干中“发现有一段特别难·.·.又回过头来对这一段进行理解”属于在学习过程中的监控和调节，故选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|19", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 19, "q": "雪山上有间房屋，里面有一只猫在抓信封”这样的联想。所运用的学习策略是（）", "opts": ["复述策略", "组织策略", "精加工策略", "计划和监控策略"], "a": 2, "exp": "精加工策略是一种将新学材料与头脑中已有知识联系起来从而增加新信息意义的深层加工策略。常用的精加工策略有记忆术（包括缩简和编歌诀、首字联词法、谐音联想法、视觉联想法、关键词法等），做笔记，提问等。题干中通过视觉联想，创造一个故事（心理想象），将所有要记的信息编在一起来记住相关词语的方法，属于精加工策略中的记忆术。A、B、D三项不符合题干，故本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|20", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 20, "q": "王老师能根据学生的学习活动判断学生使用的是什么样的学习策略，这说明学习策略具有（）", "opts": ["主动性", "迁移性", "外显性", "内隐性"], "a": 2, "exp": "外显性是指在学习中使用的一些学习策略可以直接观察到。题干中，教师通过观察学生的学习活动来判断学生所采取的学习策略类型，体现的是学习策略的外显性。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|21", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 21, "q": "思维导图属于陈述性知识学习策略中的（）", "opts": ["复述策略", "精加工策略", "组织策略", "元认知策略"], "a": 2, "exp": "组织策略是整合所学新知识之间、新旧知识之间的内在联系，形成新的知识结构。常用的组织策略有列提纲、利用图形和表格归类等。题干中“思维导图”侧重的是将知识通过思维导图的形式形成相应的知识结构和网络，体现了组织策略，故本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|22", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 22, "q": "高三下学期学习任务重、作业多。为了有更多的学习时间，林林总是把给妈妈打电话、看教育新闻等活动安排在食堂排队打饭、吃饭的时候。林林的这种安排属于学习策略中的（）", "opts": ["计划策略", "组织策略", "调节策略", "资源管理策略"], "a": 3, "exp": "资源管理策略是辅助学生管理可用的环境和资源的策略，具体包括时间管理、努力管理、环境管理、学业求助等策略。其中，时间管理策略包括统筹安排学习时间、高效利用最佳时间、灵活利用零碎时间。题干中林林充分利用排队打饭、吃饭的零碎时间来给妈妈打电话，看教育新闻等，运用的是时间管理策略。故D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|23", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 23, "q": "小彤自己一个人学习时老是会分心，一会儿摸摸笔，一会儿又看看手机，学习效率低。为了提高学习效率，她找到一个学习小组，每个周末都和学习小组的同学一起学习，大大提高了学习效率。小彤使用的学习策略是（", "opts": ["组织策略", "精加工策略", "调节策略", "资源管理策略"], "a": 3, "exp": "资源管理策略是辅助学生管理可用的环境和资源的策略，具体包括时间管理策略、学习环境管理策略、努力管理策略、学习工具利用策略和人力资源利用策略。其中，人力资源利用策略是指善于利用老师的帮助以及通过同学间的合作与讨论来学习。题干中“和学习小组的同学一起学习”体现的是对人力资源的利用。故本题选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|24", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 24, "q": "一位化学老师为了帮助学生理解记忆，把化学学科用语填进《青花瓷》歌曲中，该老师使用的是（", "opts": ["复述策略", "组织策略", "调节策略", "精加工策略"], "a": 3, "exp": "，精加工策略是一种通过形成新旧知识之间的联系，使新信息更有意义，从而促进对新信息的理解和记忆的深层加工策略。题干所用的是一种编歌诀的记忆术，属于精加工策略，D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|25", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 25, "q": "小明每次在做语文阅读理解时，会主动想“我有没有读懂这句话的意思？我的阅读速度是不是太快了？”这体现了元认知的（", "opts": ["监控功能", "计划功能", "调节功能", "评价功能"], "a": 0, "exp": "本题考查的知识点是元认知策略。元认知策略主要包括计划策略、监视策略、调节策略。A选项，元认知的监控功能是指在认知活动中，根据认知目标不断反省和监控自己的认知活动是否在沿着正确的方向进行，正确估计自己达到认知目标的程度、水平，并根据有效性标准评价各种认知行动、策略的效果。元认知的监控策略包括阅读时对注意加以跟踪、对材料进行自我提问，考试时监视自己的速度和时间。这些策略使学生警觉自己在注意和理解方面可能出现的问题。确认知目标、确定认知过程和环节、预计认知结果、选择认知策略并评估其有效性。元认知的计划策略包括设置学习目标、浏览学习材料、分析完成任务等。给学习做计划就好比是足球教练在比赛前针对对方球队的特点与出场情况提出对策。不论是完成作业，还·第六章学习策略及其教学是为了应付测验，学生在每一节课都应当有一个一般的对策。离目标时，采取相应的补救措施，及时修正、调整认知策略。例如，当学习者意识到他不理解课的某一部分时，他们就会退回去重读困难的段落、在阅读困难或不熟的材料时放慢速度、复习他们不的课程资料；测验时跳过某个难题，先做简单的题目等。调节功能能帮助小学生矫正他们的学习行为，补救理解上的不足。D选项，评价功能是指学习者能够对自己的学习态度、效果和策略的应用予以客观而全面的评价，并从中找出自己的优势和存在的不足，对自己的学习状态和水平有全面的了解。题干表述可以理解为自我提问，属于监控功能。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-06|b69|26", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-06", "chName": "", "sec": "基础练习", "no": 26, "q": "孙老师上语文课时，要求学生用自己的话写出注释。孙老师使用的教学策略是", "opts": ["复述策略", "精加工策略", "组织策略", "联想策略"], "a": 1, "exp": "在简单知识的教学中，精加工策略主要是指导学生对要记忆的材料补充细节、举出例子、做出推论，或使之与其他观念形成联想，以达到长期保持的目的。在复杂知识的教学中，可采用指导学生释义、写概要、创造类比，用自己的话写出注释、解释，自问自答等具体技术。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-07|b72|1", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-07", "chName": "", "sec": "基础练习", "no": 1, "q": "【2014年311真题34】下列选项中属于结构良好任务的是（", "opts": ["写命题作文", "为班级设计网页", "诊断电脑故障", "完成考试单选题"], "a": 3, "exp": "结构良好的任务的特点是问题和答案具有明确性，D选项完成考试单选题符合这一特点。A选项即便写命题作文，确定了主题和范围，答案也是不唯一的。B选项和C选项更需要充分发挥主观能动性，寻找解决问题的方法，均为结构不良的任务。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-07|b72|2", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-07", "chName": "", "sec": "基础练习", "no": 2, "q": "【2019年311真题37】根据问题的构成要素特点，“如何培养学生的责任感”属于(）", "opts": ["结构不良问题", "结构良好问题", "一般性问题", "认知性问题"], "a": 0, "exp": "“如何培养学生的责任感”这一问题并没有明确的解决途径，属于结构不良问题。性问题、简单的事实性问题等。例如1+1等于几？”“世界上最高山峰是什么？”D选项认知性向题是指需要经过思考和分析，且不同的人可能得出不同的答案或解释的问题，如推理性向题、复杂的问题等。例如，“社交媒体对人们社会交往的影响是什么？”“如果你是一个公司的CEO，你会如何回应全球环境的恶化？”认知性问题通常需要发挥创造力、运用逻辑分析和批判性思维等高级认知能力来解决。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-07|b75|3", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-07", "chName": "", "sec": "基础练习", "no": 3, "q": "【2011年311真题38】人在解决一系列相似的问题之后，常常出现一种以习以为常的方式方法解决新问题的倾向。这种现象被称为（）", "opts": ["学习准备", "思维定势", "功能固着", "思维阻抑"], "a": 1, "exp": "本题属于对基础概念的考查。功能固着指只看到一物体某方面常见的功能，忽视了其他方面的用途。思维定势则是以熟悉的方式做出反应的倾向，它影响着问题解决的倾向性。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-07|b75|4", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-07", "chName": "", "sec": "基础练习", "no": 4, "q": "【2023年311真题37】解决困难的新问题时，专家用于表征问题的时间与新手相比，通常（）", "opts": ["要长一些", "要短一些", "差别不大", "无法对比"], "a": 0, "exp": "在解决问题时，专家比新手快，但在解决困难的新问题时专家用于表征问题的时间比新手要长一些。这是因为专家有更多可以利用的知识，他们需要思考与当前问题最相关的知识是什么，新手则思考较少专家和新手解决问题时的差别关注公众号【研大]（1）观察力的差异，即有意义的知觉模式的差异：专家能知觉较大的有意义的刺激模式，新手不具备这样的能力，其中关键的影响因素是专门知识的水平。（2）记忆力的差异，即短时记忆和长时记忆的差异：专家的短时记忆内容比新手更多，并在熟悉的领域具有较优越的长时记忆能力。这是因为专家善于利用原有知识将新信息组成较大组块的记忆策略，来扩充短时记忆的内容；长时记忆取决于对新知识的加工程度，加工程度取决于采取的记忆策略，记忆策略的适当性又与个人的专门领域的基础知识密切相关。（3）技能执行速度的差异：专家解决问题的速度比新手快。这是因为某一领域的专家对基本技能的掌握已达到高度熟练的程度，有的已达到自动化的程度。（4）用于表征问题的时间差异：在解决问题时，专家比新手快，但在解决困难的新问题时专家用于表征问题的时间比新手要长一些。这是因为专家有更多可以利用的知识，他们需要思考与当前问题最相关的知识是什么，新手则思考较少。（5）表征的深度差异：当遇到一个新问题时，专家能很快抓住问题的实质，根据问题的内在结构表征问题。（6）自我监控技能的差异：专家倾向于更频繁地检查自己对问题的解答，而且这种检查的效果比新手更好。，第七章问题解决能力与创造性的培养问题解决的训练", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-07|b77|5", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-07", "chName": "", "sec": "基础练习", "no": 5, "q": "科学家通过观察蜻蜓飞行而发明了直升机，其中促进科学家问题解决的主要因素（）", "opts": ["定势", "迁移", "原型启发", "问题表征"], "a": 2, "exp": "本题考查影响问题解决的主要因素。原型启发是指从其他事物或现象中获得的信息对解决当前问题的启发。其中具有启发作用的事物或现象叫原型。题干中，科学家通过观察蜻蜓飞行而发明了直升机，是从观察蜻蜓飞行中获得的信息对发明直升机的启发。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-07|b77|6", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-07", "chName": "", "sec": "基础练习", "no": 6, "q": "将学期报告分解成一个个小任务，如选择题目、查阅资料、制定纲要等来逐步解决，这种方法属于问题中的（）", "opts": ["类比思维法", "手段一目的分析法", "爬山法", "逆推法"], "a": 1, "exp": "手段一目的分析法是指问题解决者不断地将当前状态和目标状态进行比较，然后采取措施尽可能地缩小这两个状态之间的差异。当问题可分成若干个各自具有目标的更小问题时，人们常常采用手段一目的分析法。题干中将大目标分解成一个个小目标的策略属于手段一目的分析法，故本题答案选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-07|b77|7", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-07", "chName": "", "sec": "基础练习", "no": 7, "q": "关于影响问题解决的因素，下列描述正确的是（）", "opts": ["思维定势和功能固着会妨碍问题解决", "思维策略是影响个体解决问题效率的最直接因素之一", "在学科问题上，掌握的知识总量越多，解题效率越高", "原型与要解决的问题在特征上有相似性，就具有启发作用"], "a": 1, "exp": "本题考查的知识点是影响问题解决的因素。思维策略指的是个体在信息加工的过程中采用的一些解决问题的计划和方法。它是影响问题解决过程的最直接的因素，直接影响着问题解决的速度和效率。B选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-07|b77|8", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-07", "chName": "", "sec": "基础练习", "no": 8, "q": "小英在解答“笼中一共5个头，16条腿，请问在笼子里有几只鸡，几只兔”这一问题时，采用如下思考：5鸡0兔5×2+0×4=10<164鸡1兔4x2+1x4=12<163鸡2兔3×2+2×4=14<162鸡3兔2×2+3×4=16=161鸡4兔1×2+4×4=18>160鸡5兔0×2+5x4=20>16答：2鸡3兔这里小英采用的问题解决策略是（", "opts": ["算法式", "启发式", "逆向搜索法", "手段一目的分析法"], "a": 0, "exp": "算法是为达到某一个目标或解决某个问题而采取的一步一步的程序。算法策略就是在问题空间中随机搜索所有可能的解决问题的方法，直至选择一种有效的方法解决问题。简而言之，算法策略就是把解决问题的方法一一进行尝试，最终找到解决问题的答案。题干中小英在解决问题时对于可能的假设逐一进行尝试，最终找到正确答案，属于算法式。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-07|b77|9", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-07", "chName": "", "sec": "基础练习", "no": 9, "q": "小明在完成论文时，思考了很久都没有写作思路，休息两天后他再次看到论文题目，突然有了写作思路，这属于问题解决中的（）", "opts": ["功能固着", "反应定势", "酝酿效应", "迁移效应"], "a": 2, "exp": "有人反复探索一个问题的解答而毫无结果时，把问题暂时搁置几小时、几天或几星期，然后再回过头来解决，这时常常可以很快找到解决方法。许多科学家在研究工作中都报告过许多这类经历。这种现象称为配酿效应。配酿效应打破了解决问题不恰当思路的定势，从而促进了新思路的产生。题干中小明在完成论文时，没有写作思路，休息后突然有了思路是配酿效应的体现。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-07|b79|10", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-07", "chName": "", "sec": "基础练习", "no": 10, "q": "【2008年311真题39】创造性思维的显著特征是（", "opts": ["严密性、流畅性、准确性", "敏捷性、严密性、独特性", "准确性、变通性、敏捷性", "流畅性、变通性、独特性"], "a": 3, "exp": "创造性思维的特征有流畅性、变通性、独特性。创造性思维不一定是严密且准确的。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-07|b79|11", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-07", "chName": "", "sec": "基础练习", "no": 11, "q": "【2024年311真题38】小组讨论中，小陈总能从多个视角提出解决问题的方案。这表明其思维具有很强的（）", "opts": ["独创性", "灵活性", "流畅性", "敏捷性"], "a": 1, "exp": "小陈能够从多个视角提出解决问题的方案，这表明他的思维具有很强的灵活性，B选项正确。灵活性指的是思维能够快速转换、适应不同情境和角度，从而提出多样化的解决方案。在小组讨论中，能够从多个视角出发提出解决方案，需要思维具有创造性及其培养灵活性，能够跳出固有思维模式，灵活应对问题。A选项独创性：独创性指的是能够提出独特、创新的想法或解决方案的能力。虽然小陈能够从多个视角提出解决问题的方案，但这并不一定代表他的解决方案都是独创性的。独创性更强调的是与众不同、具有独特性的思维能力。C选项流畅性：流畅性指的是思维能够连贯、顺畅地表达和展开的能力。虽然小陈能够提出多个解决方案，但流畅性更多关注思维表达的连贯性和条理性，而不是多样性。D选项敏捷性：敏捷性指的是思维能够快速、灵活地应对问题和变化的能力。虽然小陈能够从多个视角提出解决方案，但敏捷性更强调的是思维的反应速度和处理问题的迅速性。二、分析论述题【参考答案】（1）第一，鼓励、奖赏创造性；第二，为学生提供锻炼创造性思维的机会；第三.测验内容要灵活；第四，教师要提供创造性的示范。(2）《中国高考评价体系》突出了对学生的创造性思维能力的考查。第一.“基础性”，要求考查学生的基本知识，这些知识是创造性思维产生的基础；第二，“综合性”，要求考查学生的跨学科分析能力，它与思维的创造性联想有关；第三，“应用性”，要求考查学生的迁移能力，关乎知识、技能的创造性运用；第四，“创新性”，要求考查学生的发散思维等创造性思维能力.次夫王公次[人]这些考查要求摒弃了传统测试中只重视学生知识识记能力的倾向，更注重学生综合23261=1731637888创新能力的培养。（3）教学活动方案：①活动目标：发展学生的创造性应用能力。②活动主题：宋朝人的一天。③活动步骤：第一步：知识，师生一起学习关于宋朝人民衣、食、住、行的史料。第二步：想象，引导学生想象宋朝人民的一天。第三步：讨论，小组讨论宋朝生活情景剧剧本。第四步：创造，演绎情景剧，其他同学依据史料寻找“穿帮”镜头。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b82|1", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 1, "q": "【2008年311真题40】在社会规范学习过程中，个体不仅在行为上遵守社会规范，而且在一定程度上意识到规范的必要性和规范对个人的价值。此时其社会规范学习处于(", "opts": ["服从水平", "依从水平", "认同水平", "内化水平"], "a": 2, "exp": "于个体在“一定程度”上意识到规范的必要性和规范对个人的价值。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b82|2", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 2, "q": "【2022年311真题38】中国共产党第十九次全国代表大会的报告要求：“把社会主义核心价值观融人社会发展各方面，转化为人们的情感认同和行为习惯。”这要求社会主义核心价值观的学习应达到（", "opts": ["接受水平", "组织水平", "性格化水平", "反应水平"], "a": 2, "exp": "将社会主义核心价值观融人社会发展的各方面，转化为人们的情感认同和行为习惯强调的是个体将外在价值内化为内在的价值标准，属于性格化水平，即内化水平。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b87|3", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 3, "q": "如果某学生认为、凡是遭到批评的行为都是坏行为，而不会受惩罚的行为都是好行为，这个学生的道德发展应该处在科尔伯格所说的（）", "opts": ["前习俗水平", "后习俗水平", "习俗水平", "超习俗水平"], "a": 2, "exp": "本题考查的知识点是科尔伯格的道德发展阶段理论。惩罚与服从定向态度与品德品德的形成与培养阶段的学生服从权威或规则只是为了避免惩罚，认为受赞扬的行为就是好的，受惩罚！行为就是坏的。此题中学生处于科尔伯格道德发展的前习俗水平中的惩罚与服从定回阶段。的道德定向阶段，故本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b87|4", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 4, "q": "如果问小朋友“偷东西对不对？”小朋友的回答是“偷东西不对，因为偷东西妈妈要）打。”那么该小朋友的道德认知发展水平处于（", "opts": ["惩罚与服从定向阶段", "工具性的相对主义定向阶段", "人际协调的定向阶段", "维护权威的定向阶段"], "a": 0, "exp": "本题考查科尔伯格的道德发展阶段论。惩罚与服从定向阶段的儿童服从权威或规则只是为了避免惩罚，认为受赞扬的行为就是好的，受惩罚的行为就是坏的。他们还没有真正的道德概念。题干中小朋友认为偷东西不对是因为偷东西妈妈要打，该小朋友的道德认知发展水平处于惩罚与服从定向阶段", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b87|5", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 5, "q": "按科尔伯格的观点，划分儿童的道德发展阶段主要看其（", "opts": ["心理冲突情况", "人格发展情况", "道德行为发展情况", "道德判断能力发展情况"], "a": 3, "exp": "本题考查的知识点是科尔伯格的道德发展阶段论。科尔伯格提出道德发展阶段论，采用“道德两难故事法”，最经典的就是“海因兹偷药”的故事，让儿童对道德两难问题做出判断。科尔伯格认为儿童的道德判断普遍存在与其行为不一致的现象，但是、个体道德判断能力的发展水平越高，道德判断与行为的一致性程度越高。因此，科尔伯格认为道德发展的关键是儿童道德判断能力的发展。故D选项正确", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-psych|xl-08|b87|6", "bank": "dd1000", "subj": "edu-psych", "ch": "xl-08", "chName": "", "sec": "基础练习", "no": 6, "q": "一位出租车司机为了及时将一名有生命危险的病人送到医院抢救，闯了红灯，警察依法对出租车司机进行处罚。学生王明认为，出租车司机违反了交通法规，理应受到处罚。按科尔伯格道德发展阶段理论，王明的道德发展水平最可能处于（）", "opts": ["前习俗水平", "中习俗水平", "后习俗水平", "习俗水平"], "a": 3, "exp": "科尔伯格将道德发展分为前习俗水平、习俗水平和后习俗水平。D选项习俗水平又分为“好孩子定向阶段”和“维护权威或秩序的道德定向阶段”，题干学生认为出租车司机闯红灯，违反了法律，应受到惩罚，说明已经意识到法律的效力，但是没有意识到面对生命危险的病人，救命更重要，这体现出该学生只能对法律进行刻板遵守。故处于科尔伯格的习俗水平中维护权威与秩序的道德定向阶段，该阶段处于习俗水平。所以D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}]);
